#define A_SAINCY       0x00DC  /* [note] Saucer Y motion increment (2 bytes); SAINCX's comment "SAUCCR MOTION INCREMENTS" describes this cell too  2 bytes. */
#define SAINCY         (g.ram[A_SAINCY])
