#define A_S_CCTIM      0x00E0  /* COIN STUFF  [note] COIN65's per-mechanism (MECHS=3) electro-mechanical-counter pulse timer: sign bit set = pulse that counter on, clear = off (documented in TC65.MAC's own $CCTIM header comment).  3 bytes. */
