#define S_PSTSL        (g.ram[A_S_PSTSL])
#define S_PSTSL_AT(i)  (g.ram[(A_S_PSTSL + (i)) & 0x3FF])
#define A_S_CNSTT      0x00E7  /* [note] COIN65's coin-status/detection timers, one byte per coin mechanism (MECHS=3): two counters packed in one byte for debounced coin-switch detection (documented in TC65.MAC's own header comments)  3 bytes. */
#define S_CNSTT        (g.ram[A_S_CNSTT])
