#define S_CMODE        (g.ram[A_S_CMODE])
#define S_CMODE_AT(i)  (g.ram[(A_S_CMODE + (i)) & 0x3FF])
#define A_S_BCCNT      0x00EC  /* [note] COIN65's count of coins toward a bonus coin; cleared at power-on and game start */
