#define EXPOSY_AT(i)  (g.ram[(A_EXPOSY + (i)) & 0x3FF])
#define A_EXPOSO       0x02C8  /* [note] Per-piece orientation/spin byte for an exploding object, updated by the explosion physics loop alongside ZVELOC; copied to PTBLO2+1 to draw each piece via DRAW's D_SPCL/D_SBRT commands */
