#define ZVELOC_AT(i)  (g.ram[(A_ZVELOC + (i)) & 0x3FF])
#define A_EXPOSZ       0x02D8  /* Z POSITION FOR EXPLOSION PIECES  16 bytes. */
#define EXPOSZ         (g.ram[A_EXPOSZ])
#define EXPOSZ_AT(i)  (g.ram[(A_EXPOSZ + (i)) & 0x3FF])
#define A_TDIST        0x02E8  /* [note] Distance (high byte) from the tank to the robot, computed by DRADAR (radar display) via the Mathbox square root; read by FIREIT/ROBOT and by BUZBOM for close-range checks */
#define TDIST          (g.ram[A_TDIST])
#define TDIST_AT(i)  (g.ram[(A_TDIST + (i)) & 0x3FF])
#define A_BLIP         0x02E9  /* BLIMP TIMER  [note] Radar-blip fade timer/brightness: DRADAR sets it to $F0 when the sweep passes an enemy ("SET BRIGHTNESS OF BLIP"), decrements it by 8 every frame after (DR_BLP), and also uses it directly (AND #$E0) as the blip's own draw intensity; reaching 0 stops the sweep beep and draw.  Atari's own comment, "BLIMP TIMER", is source shorthand for this radar "blip" timer - Battlezone has no blimp object. */
#define BLIP           (g.ram[A_BLIP])
