#define A_SINT         0x02EA  /* SAUCER INTENSITY */
#define SINT           (g.ram[A_SINT])
#define SINT_AT(i)  (g.ram[(A_SINT + (i)) & 0x3FF])
#define A_PL1MOV       0x02EB  /* TEMP FOR POKEY SWITCH INPUT */
#define PL1MOV         (g.ram[A_PL1MOV])
#define PL1MOV_AT(i)  (g.ram[(A_PL1MOV + (i)) & 0x3FF])
#define A_NOR2D3       0x02EC  /* # OF R2D3'S -1 THIS GAME */
#define NOR2D3         (g.ram[A_NOR2D3])
#define NOR2D3_AT(i)  (g.ram[(A_NOR2D3 + (i)) & 0x3FF])
