#define YPOSL          (g.ram[A_YPOSL])
#define YPOSL_AT(i)  (g.ram[(A_YPOSL + (i)) & 0x3FF])
#define A_YPOSH        0x036B  /* [note] High byte of each rock's Y position, one byte per rock (see XPOSL)  5 bytes. */
